import { ChangeDetectionStrategy, Component, input } from '@angular/core';
import { FretNote } from '../note-data';

@Component({
  selector: 'app-fretboard-display',
  templateUrl: './fretboard-display.html',
  styleUrl: './fretboard-display.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class FretboardDisplayComponent {
  readonly note = input<FretNote | null>(null);
}

:host {
  display: block;
}

.fretboard-wrapper {
  position: relative;
}

.fretboard-image {
  display: block;
  width: 100%;
  height: auto;
}

.fretboard-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.note-marker {
  position: absolute;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: #fd8d32;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

