 2→import { DOCUMENT } from '@angular/common';
 3→import { RouterLink } from '@angular/router';
 4→import { ThemeService } from '../theme';
 5→
 6→const LANGUAGES = ['NL', 'DE', 'EN'] as const;
 7→const VALID_LOCALES = ['en', 'nl', 'de'] as const;
 8→
 9→const LOCALE_TO_LANGUAGE: Record<string, string> = {
10→  en: 'EN',
11→  nl: 'NL',
12→  de: 'DE',
13→};
