 4→@Injectable({ providedIn: 'root' })
 5→export class NoteDataService {
 6→  getNotesInFretRange(minFret: number, maxFret: number): FretNote[] {
 7→    if (minFret > maxFret) {
 8→      return [];
 9→    }
10→    return FRET_NOTES.filter(note => note.fret >= minFret && note.fret <= maxFret);
11→  }
12→
13→  getNotesUpToFret(maxFret: number): FretNote[] {
14→    return this.getNotesInFretRange(0, maxFret);
15→  }
16→
17→  getNotesOnFret(fret: number): FretNote[] {
18→    return this.getNotesInFretRange(fret, fret);
19→  }
20→}
